module logic;
use model {Line,Cart,Receipt}; use policy {Plan,plan,params};
use sql {Cell,Row,SqlResult,query,execute,begin,commit,rollback,params1,integer_at,expect_columns};
fn receipt(applied:Bool,replay:Bool,reason:Text)->Receipt {Receipt {applied:applied,replay:replay,reason:reason}}
fn perform(db:Native::Database,cart:Cart,key:Text)->SqlResult<Receipt> actions {db.execute,db.read,db.close} {
 let prior=try query(db,"SELECT sku1,qty1,sku2,qty2 FROM requests WHERE key=?1",params1(Cell::String(key)));
 if List::length(prior)>0 {
  let row=List::head(prior);
  try expect_columns(row,4);
  let old_sku1=try integer_at(row,0);let old_qty1=try integer_at(row,1);
  let old_sku2=try integer_at(row,2);let old_qty2=try integer_at(row,3);
  if old_sku1==cart.first.sku && old_qty1==cart.first.qty && old_sku2==cart.second.sku && old_qty2==cart.second.qty {
   Ok(receipt(false,true,"replay"))
  } else {Ok(receipt(false,false,"conflict"))}
 } else {
  let first_rows=try query(db,"SELECT available FROM inventory WHERE sku=?1",params1(Cell::Integer(cart.first.sku)));
  let second_rows=if cart.second.qty==0 {List::empty<Row>()} else {
   query(db,"SELECT available FROM inventory WHERE sku=?1",params1(Cell::Integer(cart.second.sku)))
  };
  if List::length(first_rows)==0 || (cart.second.qty>0 && List::length(second_rows)==0) {Ok(receipt(false,false,"missing"))} else {
   let first_row=List::head(first_rows);try expect_columns(first_row,1);let first_available=try integer_at(first_row,0);
   let second_available=if cart.second.qty==0 {0} else {
    let second_row=List::head(second_rows);try expect_columns(second_row,1);try integer_at(second_row,0)
   };
   if first_available<cart.first.qty || (cart.second.qty>0 && second_available<cart.second.qty) {Ok(receipt(false,false,"stock"))} else {
    try execute(db,"UPDATE inventory SET available=available-?1 WHERE sku=?2",params2(Cell::Integer(cart.first.qty),Cell::Integer(cart.first.sku)));
    if cart.second.qty>0 {
     try execute(db,"UPDATE inventory SET available=available-?1 WHERE sku=?2",params2(Cell::Integer(cart.second.qty),Cell::Integer(cart.second.sku)))
    } else {Ok(true)};
    try execute(db,"INSERT INTO requests(key,sku1,qty1,sku2,qty2) VALUES(?1,?2,?3,?4,?5)",params(key,cart));
    Ok(receipt(true,false,"reserved"))
   }
  }
 }
}
fn apply(db:Native::Database,sku1:I64,qty1:I64,sku2:I64,qty2:I64,key:Text)->SqlResult<Receipt>
actions {db.execute,db.read,db.close,db.transaction}
{
 match plan(sku1,qty1,sku2,qty2,key) {
  Invalid=>Ok(receipt(false,false,"invalid")),
  Ready(cart)=> {
   match begin(db) {
    Err(error)=>Err(error),
    Ok(started)=> {
     let outcome=perform(db,cart,key);
     match outcome {
      Err(error)=> {let ignored=rollback(db);Err(error)},
      Ok(value)=> {
       match commit(db) {
        Ok(done)=>Ok(value),
        Err(error)=> {let ignored=rollback(db);Err(error)}
       }
      }
     }
    }
   }
  }
 }
}

